#!/bin/sh
set -e

goal="Refine TerminalSummary for multiple writes and clean render"
echo "Plan:"
echo "1. Implement function to remove control characters."
echo "2. Update the extractLastLine function."
echo "3. Integrate these changes into the TerminalSummary component."

# 1. Implement function to remove control characters
cat > removeControlChars.js << 'EOF'
export function removeControlChars(data) {
  return data.replace(/[\x00-\x1F\x7F-\x9F]/g, '');
}
EOF

# 2. Update the extractLastLine function
cat > prependAndExtractLastLine.js << 'EOF'
import { removeControlChars } from './removeControlChars';

export function prependAndExtractLastLine(lastLine, currentData) {
  const combinedData = `${lastLine}${removeControlChars(currentData)}`;
  const lines = combinedData.split('\n');
  return lines[lines.length - 1];
}
EOF

# 3. Integrate these changes into the TerminalSummary component
cat > ./src/frontend/components/terminal/TerminalSummary.jsx << 'EOF'
import { createEffect, createSignal } from 'solid-js';
import { prependAndExtractLastLine } from './prependAndExtractLastLine';

export function TerminalSummary(props) {
  const [lastLine, setLastLine] = createSignal("");

  createEffect(() => {
    const newLastLine = prependAndExtractLastLine(lastLine(), props.lastWritten);
    setLastLine(newLastLine);
  });

  return <span>{lastLine()}</span>;
}
EOF

echo "\033[32mDone: $goal\033[0m\n"

